import { NextResponse } from "next/server";

import {
getNextGrandPrix,
} from "@/services/grandPrixService";

export async function GET() {
try {
const grandPrix =
await getNextGrandPrix();


if (!grandPrix) {
  return NextResponse.json(
    {
      error:
        "No se pudo detectar el próximo Gran Premio",
    },
    {
      status: 404,
    }
  );
}

return NextResponse.json({
  data: grandPrix,
});


} catch (error) {
console.error(
"Error obteniendo el próximo GP:",
error
);


return NextResponse.json(
  {
    error:
      "Error al consultar la API de MotoGP",
  },
  {
    status: 500,
  }
);


}
}
